<?php
require __DIR__.'/includes/bootstrap.php';require_role(['officer','admin']);
$page_title='Регистрация транспортного средства';$errors=[];$values=['owner_name'=>'','owner_email'=>'','make'=>'','model'=>'','vin'=>'','year'=>(string)date('Y'),'color'=>'','notes'=>''];
function generate_plate(PDO $pdo): string {
    $letters=['А','В','Е','К','М','Н','О','Р','С','Т','У','Х'];
    for($i=0;$i<500;$i++){ $plate=$letters[random_int(0,count($letters)-1)].str_pad((string)random_int(0,999),3,'0',STR_PAD_LEFT).$letters[random_int(0,count($letters)-1)].$letters[random_int(0,count($letters)-1)].'200';$s=$pdo->prepare('SELECT id FROM vehicles WHERE plate=?');$s->execute([$plate]);if(!$s->fetch())return $plate; }
    throw new RuntimeException('Не удалось сгенерировать свободный госномер. Попробуйте ещё раз.');
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();foreach($values as $k=>$v)$values[$k]=trim((string)($_POST[$k]??$v));$values['owner_email']=mb_strtolower($values['owner_email']);
 if(mb_strlen($values['owner_name'])<3)$errors[]='Укажите ФИО владельца.';
 if(!filter_var($values['owner_email'],FILTER_VALIDATE_EMAIL))$errors[]='Укажите корректный email владельца.';
 if($values['make']===''||$values['model']==='')$errors[]='Укажите марку и модель.';
 if(!preg_match('/^[A-HJ-NPR-Z0-9]{11,17}$/i',$values['vin']))$errors[]='VIN должен содержать 11–17 латинских букв и цифр (без I, O, Q).';
 if(!filter_var($values['year'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1950,'max_range'=>(int)date('Y')+1]]))$errors[]='Проверьте год выпуска.';
 if(!$errors){try{$photoPath=upload_vehicle_photo($_FILES['photo']??[]);}catch(Throwable $e){$photoPath=null;$errors[]=$e->getMessage();}}
 if(!$errors){
  $s=$pdo->prepare('SELECT id FROM vehicles WHERE UPPER(vin)=UPPER(?)');$s->execute([$values['vin']]);if($s->fetch())$errors[]='Автомобиль с таким VIN уже есть в реестре.';
 }
 if(!$errors){try{$plate=generate_plate($pdo);$s=$pdo->prepare('SELECT id FROM users WHERE LOWER(email)=LOWER(?)');$s->execute([$values['owner_email']]);$owner=$s->fetch();$pdo->beginTransaction();
   $s=$pdo->prepare("INSERT INTO vehicles(plate,vin,make,model,year,color,owner_name,owner_email,owner_user_id,status,registered_at,registered_by,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'active',CURDATE(),?,?,NOW(),NOW())");$s->execute([$plate,mb_substr($values['vin'],0,17),$values['make'],$values['model'],(int)$values['year'],$values['color']?:null,$values['owner_name'],$values['owner_email'],$owner?(int)$owner['id']:null,(int)current_user()['id'],$values['notes']?:null]);$vehicleId=(int)$pdo->lastInsertId();
   if($photoPath){$s=$pdo->prepare('INSERT INTO vehicle_photos(vehicle_id,file_path,caption,uploaded_by,created_at) VALUES(?,?,?,?,NOW())');$s->execute([$vehicleId,$photoPath,'Фото при регистрации',(int)current_user()['id']]);}
   $s=$pdo->prepare('INSERT INTO vehicle_history(vehicle_id,event_type,title,description,event_date,created_by,created_at) VALUES(?,?,?,?,CURDATE(),?,NOW())');$s->execute([$vehicleId,'registration','Первичная регистрация','Транспортное средство внесено в реестр. Госномер присвоен автоматически: '.$plate,(int)current_user()['id']]);$pdo->commit();set_flash('success','Транспорт зарегистрирован. Присвоен госномер '.$plate.'.');redirect('vehicle.php?id='.$vehicleId);
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($e instanceof PDOException)$errors[]='Не удалось сохранить запись. Возможно, VIN или госномер уже используются.';else $errors[]=$e->getMessage();}}
}
include __DIR__.'/includes/header.php';
?>
<section class="page-intro"><span class="eyebrow">Служебный раздел · ГИБДД</span><h1>Регистрация транспортного средства</h1><p>Заполните сведения — система автоматически присвоит свободный номер с кодом региона 200.</p></section>
<?php foreach($errors as $err): ?><div class="alert alert-danger"><?= e($err) ?></div><?php endforeach; ?>
<div class="split-layout"><section class="panel"><div class="panel-header"><h2>Данные автомобиля и владельца</h2><p>Поля со звёздочкой обязательны</p></div><div class="panel-body"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-grid"><div class="field"><label for="make">Марка *</label><input id="make" name="make" value="<?= e($values['make']) ?>" required placeholder="LADA"></div><div class="field"><label for="model">Модель *</label><input id="model" name="model" value="<?= e($values['model']) ?>" required placeholder="Vesta"></div><div class="field"><label for="vin">VIN *</label><input id="vin" name="vin" value="<?= e($values['vin']) ?>" minlength="11" maxlength="17" required placeholder="XTA..." autocapitalize="characters"></div><div class="field"><label for="year">Год выпуска *</label><input id="year" name="year" type="number" min="1950" max="<?= date('Y')+1 ?>" value="<?= e($values['year']) ?>" required></div><div class="field"><label for="color">Цвет</label><input id="color" name="color" value="<?= e($values['color']) ?>" placeholder="Серебристый"></div><div class="field"><label for="photo">Фото автомобиля</label><input id="photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG или WEBP, до 5 МБ</small></div><div class="field"><label for="owner_name">ФИО владельца *</label><input id="owner_name" name="owner_name" value="<?= e($values['owner_name']) ?>" required placeholder="Иван Иванов"></div><div class="field"><label for="owner_email">Email владельца *</label><input id="owner_email" name="owner_email" type="email" value="<?= e($values['owner_email']) ?>" required placeholder="name@example.com"><small>Должен совпадать с email аккаунта в банке для передачи штрафа.</small></div><div class="field span-2"><label for="notes">Служебная заметка</label><textarea id="notes" name="notes" placeholder="Дополнительные сведения, если нужны"><?= e($values['notes']) ?></textarea></div></div><div class="form-actions"><button class="btn btn-primary" type="submit">Зарегистрировать автомобиль →</button><a class="btn btn-ghost" href="index.php">Отмена</a></div></form></div></section>
<aside><section class="panel panel-pad"><span class="eyebrow">Автоматическое присвоение</span><h2 style="margin-top:12px">Региональный номер 200</h2><p class="muted tiny" style="line-height:1.8">Система сформирует свободный госномер по шаблону: одна буква, три цифры, две буквы и код региона.</p><div style="margin:20px 0"><span class="license-plate">А123ВС<span class="region">200</span></span></div><div class="summary-row"><span>Проверка уникальности</span><strong>Автоматически</strong></div><div class="summary-row"><span>История регистрации</span><strong>Создаётся сразу</strong></div><div class="summary-row"><span>Фото и карточка</span><strong>В одном профиле</strong></div></section><div class="notice" style="margin-top:14px">Перед сохранением проверьте VIN и почту владельца. Email используется для направления начислений в банк «Капитал-Стандарт».</div></aside></div>
